volumes:
  prometheus_data: {}
  grafana_data: {}

services:
  load-scale:
    build: .
    restart: unless-stopped
    depends_on:
      - prometheus
      - grafana
    environment:
      - HOST_URL=${HOST_URL}
      - HOW_MANY_USERS=${HOW_MANY_USERS:-100}
      - USERS_PER_ROOM=${SEATS_PER_ROOM:-10}
      - LOGIN_BATCH=${LOGIN_BATCH:-5}
      - SSL_ENABLED=${SSL_ENABLED:-yes}
      - DATABASE_URL=${DATABASE_URL}
      - DATABASE_NAME=${DATABASE_NAME}
      - TASK_ID=${TASK_ID:-1}
      - MESSAGE_SENDING_RATE=${MESSAGE_SENDING_RATE:-100}
      - SET_STATUS_RATE=${SET_STATUS_RATE:-10}
      - OPEN_ROOM_RATE=${OPEN_ROOM_RATE:-10}
      - READ_MESSAGE_RATE=${READ_MESSAGE_RATE:-10}
      - SUBSCRIBE_PRESENCE_RATE=${SUBSCRIBE_PRESENCE_RATE:-100}

  prometheus:
    image: prom/prometheus:v2.28.0
    volumes:
      - ./prometheus/:/etc/prometheus/
      - prometheus_data:/prometheus
    command:
      - '--config.file=/etc/prometheus/prometheus.yml'
      - '--storage.tsdb.path=/prometheus'
      - '--web.console.libraries=/usr/share/prometheus/console_libraries'
      - '--web.console.templates=/usr/share/prometheus/consoles'
    ports:
      - ${PROMETHEUS_PORT:-9090}:9090
    restart: unless-stopped

  grafana:
    image: grafana/grafana:8.0.3
    depends_on:
      - prometheus
    ports:
      - ${GRAFANA_PORT:-3300}:3000
    volumes:
      - grafana_data:/var/lib/grafana
      - ./grafana/provisioning/:/etc/grafana/provisioning/
    environment:
      - GF_SECURITY_ADMIN_PASSWORD=foobar
      - GF_USERS_ALLOW_SIGN_UP=false
      - GF_AUTH_ANONYMOUS_ENABLED=${GRAFANA_ANONYMOUS:-false}
      - GF_AUTH_ANONYMOUS_ORG_ROLE=Viewer
    restart: unless-stopped

import type { Db } from 'mongodb';
import { MongoClient } from 'mongodb';

import { BenchmarkRunner } from './BenchmarkRunner';
import type { Client } from './client/Client';
import { config } from './config';
import { rand } from './lib/rand';
import { getClients } from './macros/getClients';
import { populateDatabase, isOnlyUserPopulation } from './populate';
import { OmnichannelClient } from './client/Omnichannel';

export default (): void => {
	let agents: OmnichannelClient[];

	const b = new (class extends BenchmarkRunner {
		private db: Db | undefined;

		private client: MongoClient | undefined;

		private skippedPopulate = false;

		private adminUser: Client | undefined;

		private usernames: string[] = [];

		private extraPrefix = '-agent-';

		async init() {
			this.client = new MongoClient(config.DATABASE_URL);
			await this.client.connect();
			this.db = this.client.db(config.DATABASE_NAME);
		}

		async populate() {
			await this.init();
			// Had to duplicate here the getClients() function, because the users from profile() are not ready at this point
			if (!config.DATABASE_URL) {
				console.log('Skip populate, no DATABASE_URL');
				this.skippedPopulate = true;
				return;
			}

			if (!this.db) {
				return;
			}

			console.log('Start populate DB');

			try {
				const users = this.db.collection('users');

				console.log('Checking if the hash already exists');

				if (
					await users.findOne({
						_id: new RegExp(`${config.hash}${this.extraPrefix}`),
						roles: ['livechat-agent'],
					})
				) {
					console.log('Task skipped');
					this.skippedPopulate = true;
					return;
				}

				const results = await populateDatabase({
					userProps: {
						roles: ['livechat-agent'],
						extraPrefix: '-agent-',
						statusLivechat: 'available',
					},
					onlyUsers: true,
				});

				if (!isOnlyUserPopulation(results)) {
					return;
				}

				console.log(`Inserting users: ${results.users.length}`);

				await Promise.all([users.insertMany(results.users)]);

				console.log(results);
				this.usernames = results.users.map((user) => user.username);
				console.log('Done populating DB');
			} catch (e) {
				console.error(e);
			}
		}

		private getCurrentFromUsers(users: string[]): number[] {
			return users.map((username) => username.split('-')[4]).map(Number);
		}

		async stopdb() {
			await this.client?.close();
		}

		async setup() {
			if (!this.db) {
				return;
			}

			if (this.skippedPopulate) {
				console.log('finding users');
				// since no population was done, let's find some agents :)
				const users = this.db.collection('users');
				this.usernames = (
					await users
						.find(
							{
								_id: new RegExp(`${config.hash}${this.extraPrefix}`),
								roles: ['livechat-agent'],
							},
							{ projection: { username: 1 } },
						)
						.toArray()
				).map((user) => user.username);
			}

			console.log(this.usernames);
			agents = await getClients(OmnichannelClient, config.HOW_MANY_USERS, this.extraPrefix, this.getCurrentFromUsers(this.usernames));

			const settings = this.db.collection('rocketchat_settings');
			await settings.updateOne(
				// @ts-expect-error _id is an ObjectID for mongo, but a string for settings :)
				{ _id: 'Livechat_Routing_Method' },
				{ $set: { value: 'Manual_Selection' } },
			);
		}
	})({
		getRoutingConfig: config.ROUTING_CONFIG_PER_SEC,
		getQueuedInquiries: config.QUEUED_INQUIRIES_PER_SEC,
		takeInquiry: config.TAKE_INQUIRY_PER_SEC,
	});

	b.on('ready', async () => {
		console.log('[AGENTS] Ready');
		await b.stopdb();
	});

	b.on('getRoutingConfig', async () => {
		const agent = rand(agents);
		await agent.getRoutingConfig();
		const { departments } = (await agent.getAgentDepartments()) || {
			departments: [],
		};
		const deps = departments.map((department) => department.departmentId);

		await agent.subscribeDeps(deps);
	});

	b.on('getQueuedInquiries', async () => {
		const agent = rand(agents);
		await agent.getQueuedInquiries();
	});

	b.on('takeInquiry', async () => {
		const agent = rand(agents);
		const response = await agent.getQueuedInquiries();
		if (!response?.inquiries) {
			return;
		}

		const { inquiries } = response;
		// if there's inquiries, do the processing
		// Everytime we get the event, we'll take one of the inquiries if any, and
		// do the normal agent operation
		if (!inquiries.length) {
			return;
		}

		const processedInquiry = rand(inquiries);
		try {
			// Re-fetch inquiry
			await agent.getInquiry(processedInquiry._id);
			// open room
			await agent.openLivechatRoom(processedInquiry.rid, processedInquiry.v._id);
			// fetch info
			await agent.getVisitorInfo(processedInquiry.v._id);
			// take inquiry
			await agent.takeInquiry(processedInquiry._id);
		} catch (e) {
			console.error(e);
		}
	});

	b.on('message', async () => {
		const agent = rand(agents);
		const sub = agent.getRandomLivechatSubscription();

		if (!sub) {
			return;
		}

		try {
			await agent.sendMessage('Hello, I am an agent', sub.rid);
		} catch (e) {
			console.error(e);
		}
	});

	b.run().catch((e) => {
		console.error('Error during run', e);
	});
};

{
  "src/**/*.{js,ts}": [
    "npm run eslint --fix --"
  ]
}

{
  "extends": "./tsconfig.json",
  "exclude": ["**/*.spec.ts"]
}

module.exports = {
  preset: 'ts-jest',
  errorOnDeprecated: true,
  testMatch: ['<rootDir>/src/**/*.spec.ts'],
  globals: {
    'ts-jest': {
      tsconfig: {
        noUnusedLocals: false,
        noUnusedParameters: false,
      },
    },
  },
};

module.exports = {
	extends: '@rocket.chat/eslint-config',
	env: {
		jest: true,
	},
	overrides: [
		{
			files: ['**/*.ts', '**/*.tsx'],
			rules: {
				'@typescript-eslint/indent': ['off'],
				'@typescript-eslint/no-misused-promises': [
					'error',
					{
						checksVoidReturn: {
							arguments: false,
						},
					},
				],
				'@typescript-eslint/no-floating-promises': 'error',
			},
			parserOptions: {
				project: ['./tsconfig.json'],
			},
		},
	],
};

{
  "entryPoints": [
    "src/index.ts"
  ],
  "out": "../../static/rocket-chat-load-tester"
}

{
  "restartable": "rs",
  "ignore": [".git", "node_modules/**/node_modules"],
  "verbose": true,
  "execMap": {
    "ts": "node --inspect --require ts-node/register"
  },
  "watch": ["src/"],
  "env": {
    "NODE_ENV": "development"
  },
  "ext": "js,json,ts"
}

{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "module": "commonjs",
    "outDir": "./dist/cjs"
  },
  "exclude": ["**/*.spec.ts"]
}

declare module '@koa/router';

// Typed version of Object.keys
declare interface ObjectConstructor {
	keys<T>(o: T): import('../src/definifitons').ObjectKeys<T>;
}

import type { ObjectId } from 'mongodb';

export type Room = {
	_id: string;
	name: string;
	fname: string;
	t: string;
	msgs: number;
	usersCount: number;
	u: Pick<User, '_id' | 'username'>;
	customFields: unknown;
	broadcast: false;
	encrypted: false;
	ts: Date;
	ro: false;
	default: false;
	sysMes: true;
	_updatedAt: Date;
};

export type Subscription = {
	_id: string;
	rid: string;
	name: string;
	t: string;
};

export type User = {
	_id: string;
	username: string;
	createdAt: Date;
	services: {
		password: {
			bcrypt: string; // performance
		};
		resume: {
			loginTokens: [];
		};
	};
	type: 'user';
	status: string;
	active: true;
	_updatedAt: Date;
	roles: ['user'];
	lastLogin: Date;
	statusConnection: string;
	__rooms: string[];
};

type WithoutId<T> = Omit<T, '_id'>;
export type Storable<T> = WithoutId<T> & { _id: ObjectId | undefined };

export type Department = {
	name: string;
	departmentId: string;
};

export type Inquiry = {
	_id: string;
	rid: string;
	v: {
		_id: string;
	};
};

export type Visitor = {
	_id: string;
	name: string;
};

// eslint-disable-next-line @typescript-eslint/ban-types
export type ObjectKeys<T> = T extends object ? (keyof T)[] : T extends number ? [] : T extends Array<any> | string ? string[] : never;

import FormData from 'form-data';
import fetch from 'node-fetch';

import agent from './agent';
import type { ObjectKeys } from './definifitons';
import profile from './profile';

import './server';

(global as any).fetch = fetch;
(global as any).FormData = FormData;

const actions = {
	agent,
	profile,
};

const actionsParam = process.argv[2];
let actionList: ObjectKeys<typeof actions>;

if (!actionsParam || !actionsParam.includes('process')) {
	// will run only 'profile' by default
	actionList = ['profile'];
} else {
	actionList = actionsParam.split('--process=').pop()?.split(',') as ObjectKeys<typeof actions>;
}

actionList.forEach((action) => {
	console.log(`Running action: ${action}`);
	actions[action]();
});

